def _load(name, blob):
    m = _t.ModuleType(name); m.__file__ = name + '.py'
    exec(compile(_z.decompress(_b.b85decode(blob)).decode(), name + '.py', 'exec'), m.__dict__)
    return m
_MK = _load('kb_moe', _K)
_MA = _load('aly_moe', _A)
ALY_BS = (8, 32)
def prepare(weights):
    return {'k': _MK.prepare(weights), 'a': _MA.prepare(weights)}
def kernel_fn(data, state):
    if data['hidden_states'].shape[0] in ALY_BS:
        return _MA.kernel_fn(data, state['a'])
    return _MK.kernel_fn(data, state['k'])
